INSERT OR IGNORE INTO brief_items (item_id,url,title,summary,why_it_matters,source,published_at,category,region,tags_json,report_date,source_generated_at,collection_type,is_top_pick,sort_order,content_hash,status,first_seen_at,last_seen_at,refreshed_at) VALUES ('radar:https://www.marktechpost.com/2026/10/28/nvidia-nemotron-3-5-transcribe-open-speech-llm/','https://www.marktechpost.com/2026/10/28/nvidia-nemotron-3-5-transcribe-open-speech-llm/','英伟达开源 Nemotron 3.5 Transcribe：30B MoE 语音模型，支持40种语言','英伟达发布 Nemotron 3.5 Transcribe，这是一个开放权重的语音大模型，激活参数为4.3B。它支持40种语言转录，新增说话人标签和词级时间戳，在英语 Open ASR 排行榜上平均词错误率为4.71%。','开放权重的语音模型若在词错误率上具备竞争力，可降低多语言转录的部署门槛，并减少对专有API的依赖。','MarkTechPost','2026-10-29T04:41:24+00:00','技术突破','','[]','2026-10-29','2026-10-29T13:46:57.225360+08:00','global_top5',1,0,'a793a4e09840237a','current','2026-10-29T06:29:03.943Z','2026-10-29T06:29:03.943Z','2026-10-29T06:29:03.943Z');
