INSERT OR IGNORE INTO brief_items (item_id,url,title,summary,why_it_matters,source,published_at,category,region,tags_json,report_date,source_generated_at,collection_type,is_top_pick,sort_order,content_hash,status,first_seen_at,last_seen_at,refreshed_at) VALUES ('radar:https://techcrunch.com/2026/10/28/google-expands-ai-search-ads-globally-as-core-ad-growth-slows/','https://techcrunch.com/2026/10/28/google-expands-ai-search-ads-globally-as-core-ad-growth-slows/','谷歌在全球扩展 AI 搜索广告，核心广告增长放缓','谷歌宣布在全球范围扩展 AI 搜索广告。该消息与母公司 Alphabet 第三季度财报同时发布，财报显示营收同比增长25%至1276亿美元。','在核心广告增速放缓之际，把广告嵌入 AI 搜索是谷歌维持广告收入增长的关键路径。','TechCrunch AI','2026-10-28T21:48:37+00:00','商业动态','','[]','2026-10-29','2026-10-29T13:46:57.225360+08:00','global_top5',1,2,'6197392d37e88d62','current','2026-10-29T06:29:03.943Z','2026-10-29T06:29:03.943Z','2026-10-29T06:29:03.943Z');
