INSERT OR IGNORE INTO brief_items (item_id,url,title,summary,why_it_matters,source,published_at,category,region,tags_json,report_date,source_generated_at,collection_type,is_top_pick,sort_order,content_hash,status,first_seen_at,last_seen_at,refreshed_at) VALUES ('radar:https://techcrunch.com/2026/10/28/microsoft-recorded-10-billion-in-revenue-from-openai/','https://techcrunch.com/2026/10/28/microsoft-recorded-10-billion-in-revenue-from-openai/','微软从 OpenAI 相关业务录得100亿美元收入','微软表示，在截至9月30日的季度中，来自与 OpenAI 商业安排（包括收入分成）的收入为100亿美元。这凸显了双方合作中依然巨大的财务依赖。','该数字量化了微软业绩对 OpenAI 合作关系的依赖程度，也反映两家公司在商业上的深度绑定。','TechCrunch AI','2026-10-28T21:34:30+00:00','','','[]','2026-10-29','2026-10-29T13:46:57.225360+08:00','global_news',0,4,'e93c2f2db347a932','current','2026-10-29T06:29:03.943Z','2026-10-29T06:29:03.943Z','2026-10-29T06:29:03.943Z');
