INSERT OR IGNORE INTO brief_items (item_id,url,title,summary,why_it_matters,source,published_at,category,region,tags_json,report_date,source_generated_at,collection_type,is_top_pick,sort_order,content_hash,status,first_seen_at,last_seen_at,refreshed_at) VALUES ('radar:https://techcrunch.com/2026/10/28/microsoft-hits-10-quarters-of-record-breaking-revenue-in-a-row/','https://techcrunch.com/2026/10/28/microsoft-hits-10-quarters-of-record-breaking-revenue-in-a-row/','微软连续10个季度创下营收纪录','微软周三公布季度营收再创新高，达923亿美元，同比增长19%。无论 AI 未来如何，当前形势对微软依然非常有利。','连续创纪录的营收为微软持续投入 AI 基础设施与产品提供了财务缓冲。','TechCrunch AI','2026-10-28T21:25:30+00:00','','','[]','2026-10-29','2026-10-29T13:46:57.225360+08:00','global_news',0,5,'eb7f6e09a6350fd4','current','2026-10-29T06:29:03.943Z','2026-10-29T06:29:03.943Z','2026-10-29T06:29:03.943Z');
