INSERT OR IGNORE INTO brief_items (item_id,url,title,summary,why_it_matters,source,published_at,category,region,tags_json,report_date,source_generated_at,collection_type,is_top_pick,sort_order,content_hash,status,first_seen_at,last_seen_at,refreshed_at) VALUES ('radar:https://www.technologyreview.com/2026/10/28/1147709/creating-ai-value-with-enterprise-context/','https://www.technologyreview.com/2026/10/28/1147709/creating-ai-value-with-enterprise-context/','以企业上下文创造 AI 价值','企业中可能同时运行多种 AI 平台、系统和工具，例如 AI 客服平台、对话助手以及工作流与流程自动化工具。它们各自先进且响应迅速，但实际产出的结果和行动可能出错、混乱或缺乏依据。','文章指出，AI 工具的效果取决于能否接入企业自身的上下文，否则再先进的系统也可能给出错误行动。','MIT Technology Review AI','2026-10-28T20:32:02+00:00','','','[]','2026-10-29','2026-10-29T13:46:57.225360+08:00','global_news',0,6,'b61b4b7a08c4b784','current','2026-10-29T06:29:03.943Z','2026-10-29T06:29:03.943Z','2026-10-29T06:29:03.943Z');
